func (s *Service) availableLeadKinds(ctx context.Context, cfg config.Config) []string {
	available := []string{}
	if s.Herdr != nil {
		if manifests, err := s.herdrCall(ctx, "server.agent_manifests", map[string]any{}); err == nil {
			available = availableAgentKinds(manifests)
		}
	}
	if len(available) == 0 {
		for kind := range cfg.Kinds {
			if _, err := exec.LookPath(agentCLIName(kind)); err == nil {
				available = append(available, kind)
			}
		}
		sort.Strings(available)
	}
	return available
}

func refuseForeignLeadWorkspace(snapshot herdr.Snapshot, project store.Project, callerPaneID, workspaceID string) error {
	return refuseForeignLeadWorkspaceWithCommand(snapshot, project, callerPaneID, workspaceID, "posse up")
}

func refuseForeignLeadWorkspaceWithCommand(snapshot herdr.Snapshot, project store.Project, callerPaneID, workspaceID, command string) error {
	ownLabel := "posse:" + project.Name + ":lead"
	recovery := "Open a new Herdr workspace for this Project, then run `" + command + "` there"
	for _, pane := range snapshot.Panes {
		if pane.Label == "" || pane.Label == ownLabel || !strings.HasPrefix(pane.Label, "posse:") || !strings.HasSuffix(pane.Label, ":lead") {
			continue
		}
		other := strings.TrimSuffix(strings.TrimPrefix(pane.Label, "posse:"), ":lead")
		if pane.PaneID == callerPaneID {
			return axi.Failure("lead_workspace_conflict", fmt.Sprintf("cannot start Project %s from Project %s's Lead pane in Herdr workspace %s. %s", project.Name, other, pane.WorkspaceID, recovery), false, recovery)
		}
		if pane.WorkspaceID == workspaceID {
			return axi.Failure("lead_workspace_conflict", fmt.Sprintf("Herdr workspace %s contains the Lead pane for Project %s. %s", workspaceID, other, recovery), false, recovery)
		}
	}
	return nil
}

func refuseForeignLeadForProject(snapshot herdr.Snapshot, project store.Project, callerPaneID string) error {
	workspaceID := project.HerdrWorkspaceID
	if foundID, found := leadWorkspace(snapshot, project); found {
		workspaceID = foundID
	}
	return refuseForeignLeadWorkspace(snapshot, project, callerPaneID, workspaceID)
}

func (s *Service) upCore(ctx *axi.Context, args []string) (returnErr error) {
	parsed, err := parseUpArgs(args)
	if err != nil {
		return err
	}
	if len(parsed.Positionals) != 0 {
		return axi.Usage("up does not take positional arguments")
	}
	if parsed.All {
		if parsed.Kind != "" || parsed.Name != "" || parsed.Replace || parsed.Yes {
			return axi.Usage("up --all takes no other flags; each Lead restores with its recorded agent kind")
		}
		return s.restoreAll(ctx)
	}
	if s.herdrContext == nil || !s.herdrContext() {
		return axi.Failure("not_in_herdr", "posse up must run from a Herdr pane", false, "Open a shell pane in Herdr and run `posse up`")
	}
	db, home, err := s.openDB()
	if err != nil {
		return err
	}
	defer db.Close()
	dir, err := currentDir()
	if err != nil {
		return err
	}
	actor := s.configCaller(ctx.Context, db)
	if actor.role == "worker" {
		return axi.Failure("lead_only", "posse up cannot run from a Worker pane", false, "Run `posse up` from a User or Lead shell in the Project folder")
	}
	if task, taskErr := taskForPath(ctx.Context, db, dir); taskErr == nil {
		plan, planErr := task.AdmittedPlan()
		if planErr != nil {
