		if len(process.Argv) < 2 {
			continue
		}
		interpreter := strings.ToLower(filepath.Base(process.Argv[0]))
		switch interpreter {
		case "bash", "node", "perl", "python", "python2", "python3", "ruby", "sh":
			if strings.EqualFold(filepath.Base(process.Argv[1]), agent) {
				return true
			}
		}
	}
